-- S519 SkyCloudberry, 2026-10-29: Sam's saved funding passages name the column Funds Qualified So Far.
-- The CSM team via Sam, 2026-10-29: "CSM team suggests changing Curr to 'Funds Qualified So Far' and I think it would
-- avoid confusion. advise". S518 advised yes; the code renames every header, hover, the CSV and the house passages
-- (#2560). Three of Sam's saved passages in Scenario 4 (the published scenario) still say Curr / current total, and a
-- saved passage outranks the house text, so this changes those words alone and leaves every other word his.
-- Rule 10: one guarded UPDATE; the guard is each passage's exact BEFORE value, so an edit of his to any of the three
-- since this read makes it update nothing (rows 0: re-read and redo). Other saves elsewhere in the config are untouched.
-- BEFORE (read 2026-10-29 ~18:57Z through the Supabase MCP; config updated_at 2026-10-29 17:57:21Z, slee@cccco.edu):
--   text.reading: "Awards are reflected as max credit (CE) and noncredit (NC) next to the current (curr) amount, which is based on the current outcomes. The CPL an institution actually posts in MAP counts toward its award — Current Total = cap × (actual ÷ target), capped at 100% (an institution at half its target qualifies for half its cap. The current total is the amount dispersed to the colleges according to the funding timeline). Remaining funding rolls forward.\n\nNote: Noncredit awards are based on separate outcomes described in the Noncredit Funding Rules section."
--   text.college_intro: "Per college potential funds (max funds) and the FTES targets on which the funding is based are listed below. Max funds are based on measurable outcomes and allocated as credit and noncredit subtotals, shown as Max CR Funds and Max NC Funds. The Curr (current) columns show the funding qualifying so far. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks the third, the Veteran Star. Click an institution to see more detail."
--   text.x_table_intro: "The Dashboard lists the potential funding and FTES for each institution. The Max Funds column lists the potential funding to be awarded for both credit and noncredit CPL priorities. Curr Funds (current) shows the funding colleges qualify for so far. Click a college row to see details for each priority. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks whether the college has achieved Veteran Star status, which is one of the qualifying conditions."
-- ROLLBACK: the same statement with BEFORE and AFTER swapped (or Restore / Edit on the tab's passage).
update public.cpl_funding_config
set config = jsonb_set(jsonb_set(jsonb_set(config,
      '{projects,cpl-implementation,scenarios,Scenario 4,text,reading}', $j$"Awards are reflected as max credit (CE) and noncredit (NC) next to the Funds Qualified So Far amount, which is based on the current outcomes. The CPL an institution actually posts in MAP counts toward its award — Funds Qualified So Far = cap × (actual ÷ target), capped at 100% (an institution at half its target qualifies for half its cap. Funds Qualified So Far is the amount dispersed to the colleges according to the funding timeline). Remaining funding rolls forward.\n\nNote: Noncredit awards are based on separate outcomes described in the Noncredit Funding Rules section."$j$::jsonb),
      '{projects,cpl-implementation,scenarios,Scenario 4,text,college_intro}', $j$"Per college potential funds (max funds) and the FTES targets on which the funding is based are listed below. Max funds are based on measurable outcomes and allocated as credit and noncredit subtotals, shown as Max CR Funds and Max NC Funds. The Funds Qualified So Far columns show the funding qualifying to date. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks the third, the Veteran Star. Click an institution to see more detail."$j$::jsonb),
      '{projects,cpl-implementation,scenarios,Scenario 4,text,x_table_intro}', $j$"The Dashboard lists the potential funding and FTES for each institution. The Max Funds column lists the potential funding to be awarded for both credit and noncredit CPL priorities. Funds Qualified So Far shows the funding colleges qualify for to date. Click a college row to see details for each priority. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks whether the college has achieved Veteran Star status, which is one of the qualifying conditions."$j$::jsonb)
where id = 'default'
  and config #> '{projects,cpl-implementation,scenarios,Scenario 4,text,reading}' = $j$"Awards are reflected as max credit (CE) and noncredit (NC) next to the current (curr) amount, which is based on the current outcomes. The CPL an institution actually posts in MAP counts toward its award — Current Total = cap × (actual ÷ target), capped at 100% (an institution at half its target qualifies for half its cap. The current total is the amount dispersed to the colleges according to the funding timeline). Remaining funding rolls forward.\n\nNote: Noncredit awards are based on separate outcomes described in the Noncredit Funding Rules section."$j$::jsonb
  and config #> '{projects,cpl-implementation,scenarios,Scenario 4,text,college_intro}' = $j$"Per college potential funds (max funds) and the FTES targets on which the funding is based are listed below. Max funds are based on measurable outcomes and allocated as credit and noncredit subtotals, shown as Max CR Funds and Max NC Funds. The Curr (current) columns show the funding qualifying so far. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks the third, the Veteran Star. Click an institution to see more detail."$j$::jsonb
  and config #> '{projects,cpl-implementation,scenarios,Scenario 4,text,x_table_intro}' = $j$"The Dashboard lists the potential funding and FTES for each institution. The Max Funds column lists the potential funding to be awarded for both credit and noncredit CPL priorities. Curr Funds (current) shows the funding colleges qualify for so far. Click a college row to see details for each priority. The numbered pie before each name shows which of the three minimum conditions the institution meets, and a star marks whether the college has achieved Veteran Star status, which is one of the qualifying conditions."$j$::jsonb
returning updated_at as new_updated_at,
  config #>> '{projects,cpl-implementation,scenarios,Scenario 4,text,x_table_intro}' as x_table_intro;
